using System;
using System.Linq;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
public static class ConfigureVehicleEquipment {
static int Anchors(GameObject root){int count=0;foreach(var r in root.GetComponentsInChildren<MeshRenderer>(true))if(r.sharedMaterials.Any(m=>m!=null&&(m.name.Contains("Trunk_Birch")||m.name.Contains("Trunk_Oak")))){var collider=r.GetComponent<Collider>();if(collider!=null&&r.GetComponent<WinchAnchorSurface>()==null){r.gameObject.AddComponent<WinchAnchorSurface>();count++;}}return count;}
public static string Main(){if(Application.isPlaying)throw new Exception("Stop Play first");var v=UnityEngine.Object.FindAnyObjectByType<VehiclePhysics>();string path="Assets/Game/Generated/AuthoredForestPajero/Pajero equipment.asset";var c=AssetDatabase.LoadAssetAtPath<VehicleEquipmentProfile>(path);if(c==null){c=ScriptableObject.CreateInstance<VehicleEquipmentProfile>();AssetDatabase.CreateAsset(c,path);}var p=v.profile;p.equipment=c;p.dirtLongitudinal=.36f;p.grassLongitudinal=.28f;p.forwardSlidingGrip=.60f;p.baseSoilChainedLongitudinal=.64f;p.baseSoilChainedLateral=.68f;p.chainsSlidingGrip=.78f;for(int i=0;i<p.axles.Length;i++){p.axles[i].chains=true;p.axles[i].primaryDrive=i==p.axles.Length-1;p.axles[i].limitedSlipTorqueNm=110;p.axles[i].limitedSlipCoupling=8;}c.defaultFourWheelDrive=false;
foreach(var surface in UnityEngine.Object.FindObjectsByType<ForestDrivingSurface>())if(surface.cover==ForestDrivingSurface.Cover.Mud){surface.forwardGrip=.36f;surface.chainsImproveGrip=true;surface.chainedForwardGrip=.64f;EditorUtility.SetDirty(surface);}
var chains=v.GetComponent<TruckChains>();var existing=chains.wheelChainVisuals;var material=existing.First(x=>x!=null).GetComponentInChildren<Renderer>(true).sharedMaterial;foreach(var go in existing)if(go!=null)UnityEngine.Object.DestroyImmediate(go);chains.wheelChainVisuals=new GameObject[v.axles.Length*2];for(int a=0;a<v.axles.Length;a++)for(int side=0;side<2;side++){var hub=side==0?v.axles[a].leftVisual:v.axles[a].rightVisual;var root=new GameObject("Tire chains axle "+a+" side "+side);root.transform.SetParent(hub,false);for(int j=0;j<16;j++){float angle=j*Mathf.PI*2/16;var link=GameObject.CreatePrimitive(PrimitiveType.Cube);UnityEngine.Object.DestroyImmediate(link.GetComponent<Collider>());link.name="Chain cross link";link.transform.SetParent(root.transform,false);link.transform.localPosition=new Vector3(0,Mathf.Cos(angle)*p.axles[a].wheelRadius,Mathf.Sin(angle)*p.axles[a].wheelRadius);link.transform.localRotation=Quaternion.Euler(angle*Mathf.Rad2Deg,0,0);link.transform.localScale=new Vector3(.31f,.018f,.025f);link.GetComponent<Renderer>().sharedMaterial=material;}root.SetActive(false);chains.wheelChainVisuals[a*2+side]=root;}
if(v.GetComponent<VehicleWinch>()==null)v.gameObject.AddComponent<VehicleWinch>();int anchors=0;foreach(var root in v.gameObject.scene.GetRootGameObjects())anchors+=Anchors(root);var route=UnityEngine.Object.FindAnyObjectByType<AuthoredForestRoute>();foreach(var prefab in route.arms.SelectMany(a=>a.modules).Distinct()){string prefabPath=AssetDatabase.GetAssetPath(prefab);var root=PrefabUtility.LoadPrefabContents(prefabPath);try{anchors+=Anchors(root);PrefabUtility.SaveAsPrefabAsset(root,prefabPath);}finally{PrefabUtility.UnloadPrefabContents(root);}}
EditorUtility.SetDirty(p);EditorUtility.SetDirty(c);EditorUtility.SetDirty(v);EditorUtility.SetDirty(chains);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(v.gameObject.scene);if(!EditorSceneManager.SaveScene(v.gameObject.scene))throw new Exception("Save failed");return "Configured shared equipment in vehicle physics profile; default rear drive, H AWD, 1 all-wheel chains, 2 physical winch, B horn. Chain visuals="+chains.wheelChainVisuals.Length+"; anchor collider markers="+anchors;}
}
